package vn.rtr.aeris.diagnostic;
import java.util.*;
/** Pure bounded report model; no Android APIs, flight bindings or device attestation. */
public final class CaptureSession {
 public static final int LIMIT=300;
 public final String id=UUID.randomUUID().toString();
 private final List<Map<String,Object>> lifecycle=new ArrayList<>(),trace=new ArrayList<>();
 private long sequence=0, dropped=0;private boolean capturing=false;
 public static Map<String,Object> map(Object... pairs){Map<String,Object> m=new LinkedHashMap<>();if(pairs.length%2!=0)throw new IllegalArgumentException();for(int i=0;i<pairs.length;i+=2)m.put((String)pairs[i],pairs[i+1]);return m;}
 private static void time(long t){if(t<0)throw new IllegalArgumentException("Negative elapsed time");}
 private Map<String,Object> event(String kind,long at,Map<String,Object> detail){time(at);return map("seq",++sequence,"event",kind,"atElapsedMs",at,"detail",detail);}
 private void add(List<Map<String,Object>> list,Map<String,Object> value){list.add(value);if(list.size()>LIMIT){list.remove(0);dropped++;}}
 public void lifecycle(String name,long at){lifecycle(name,at,map());}
 public void lifecycle(String name,long at,Map<String,Object> detail){if(!Arrays.asList("create","start","resume","pause","stop","destroy","focus-gained","focus-lost","input-added","input-removed","input-changed").contains(name))throw new IllegalArgumentException("Lifecycle event");add(lifecycle,event(name,at,detail));if(name.equals("pause")||name.equals("focus-lost")||name.equals("stop"))capture(false,at);}
 public void capture(boolean value,long at){if(capturing!=value){capturing=value;add(trace,event(value?"capture-start":"capture-stop",at,map("noFlightBinding",true)));}}
 public boolean capturing(){return capturing;}
 public boolean raw(String kind,long at,Map<String,Object> detail){if(!capturing)return false;if(!kind.equals("key")&&!kind.equals("axis"))throw new IllegalArgumentException("Raw event");json(detail);add(trace,event(kind,at,copyMap(detail)));return true;}
 public Map<String,Object> report(String utc,String context,String alias,String revision,String buildId,List<Map<String,Object>> observations){if(!context.equals("physical-or-unknown")&&!context.equals("emulator"))throw new IllegalArgumentException("Context");if(alias.length()>80||revision.length()>80||observations.size()!=4)throw new IllegalArgumentException("Report bounds");return map("format","aeris-native-capture","version",1,"platform","android","scope","diagnostic-read-only","operational",false,"captureId",id,"capturedAt",utc,"context",context,"identity",map("alias",alias.trim(),"revision",revision.trim(),"declaredProduct","HeraHub","confirmation","operator-unverified"),"app",map("package","vn.rtr.aeris.diagnostic","version","0.6.0","buildId",buildId),"observations",copy(observations),"lifecycle",copy(lifecycle),"inputTrace",copy(trace),"droppedEvents",dropped,"unknowns",map("radioTransport",null,"channelMap",null,"calibration",null,"liveVideoEndpoint",null,"decoderConcurrency",null,"rtkRoute",null,"controllerBatteryApi",null),"limits",map("codecEnumerationOnly",true,"noFlightBinding",true,"unattested",true));}
 public static Object copy(Object x){if(x instanceof Map){Map<String,Object> m=new LinkedHashMap<>();for(Map.Entry<?,?> e:((Map<?,?>)x).entrySet())m.put((String)e.getKey(),copy(e.getValue()));return m;}if(x instanceof List){List<Object> a=new ArrayList<>();for(Object e:(List<?>)x)a.add(copy(e));return a;}return x;}
 @SuppressWarnings("unchecked") private static Map<String,Object> copyMap(Map<String,Object> x){return (Map<String,Object>)copy(x);}
 public static String json(Object value){if(value==null)return "null";if(value instanceof String){StringBuilder b=new StringBuilder("\"");for(char c:((String)value).toCharArray()){switch(c){case '"':b.append("\\\"");break;case '\\':b.append("\\\\");break;case '\n':b.append("\\n");break;case '\r':b.append("\\r");break;case '\t':b.append("\\t");break;default:if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}if(value instanceof Boolean)return value.toString();if(value instanceof Number){if(!Double.isFinite(((Number)value).doubleValue()))throw new IllegalArgumentException("Non-finite value");return value.toString();}if(value instanceof Map){List<String> parts=new ArrayList<>();for(Object key:((Map<?,?>)value).keySet()){if(!(key instanceof String))throw new IllegalArgumentException();parts.add(json(key)+":"+json(((Map<?,?>)value).get(key)));}return "{"+String.join(",",parts)+"}";}if(value instanceof Iterable){List<String> parts=new ArrayList<>();for(Object item:(Iterable<?>)value)parts.add(json(item));return "["+String.join(",",parts)+"]";}throw new IllegalArgumentException("Unsupported JSON value");}
}
